export const handler = async (input) => {
  const maximums = { buyer_business_model_fit: 20, product_category_fit: 20, market_channel_fit: 15, commercial_moq_fit: 15, company_scale_fit: 10, distribution_pattern_fit: 10, historical_win_similarity: 10 };
  const dimensions = input.dimensions || {};
  const dimension_scores = {};
  const reason_codes = [];
  const evidenceIds = [];
  let score = 0;
  let coverage = 0;
  for (const [key, maximum] of Object.entries(maximums)) {
    const fact = dimensions[key] || {};
    const available = fact.available === true;
    const profileCoverage = Math.max(0, Math.min(100, Number(fact.profile_coverage || 0)));
    const fit = Math.max(0, Math.min(1, Number(fact.fit || 0)));
    const ids = Array.isArray(fact.evidence_ids) ? fact.evidence_ids.filter(Boolean) : [];
    const points = available ? Math.round(maximum * fit) : 0;
    const covered = available ? maximum * profileCoverage / 100 : 0;
    score += points;
    coverage += covered;
    evidenceIds.push(...ids);
    const reason = fact.reason_code || (available ? (points > 0 ? key.toUpperCase() + '_MATCH' : key.toUpperCase() + '_NO_MATCH') : key.toUpperCase() + '_DATA_MISSING');
    reason_codes.push(reason);
    dimension_scores[key] = { points, maximum, covered_weight: Math.round(covered * 100) / 100, reason_codes: [reason], evidence_ids: ids };
  }
  const profileType = String(input.reference_profile_type || 'MANAGEMENT_BASELINE');
  const profileCoverage = Number(input.profile_feature_coverage || 0);
  const suppress = profileType === 'HISTORICAL_CUSTOMER_ICP' && profileCoverage < 60;
  const finalCoverage = Math.round(Math.min(100, coverage) * 100) / 100;
  const matchScore = suppress ? null : Math.max(0, Math.min(100, score));
  if (suppress) reason_codes.push('HISTORICAL_PROFILE_COVERAGE_BELOW_60');
  const dpvHigh = Number(input.dpv_score || 0) >= 55;
  const matchHigh = matchScore !== null && matchScore >= 60;
  const opportunity_matrix = dpvHigh && matchHigh ? 'PRIORITY_OPPORTUNITY' : dpvHigh ? 'STRATEGIC_MANUAL_REVIEW' : matchHigh ? 'EVIDENCE_GAP_REVIEW' : 'LOWER_PRIORITY';
  return {
    match_score: matchScore,
    coverage_percent: finalCoverage,
    reference_profile_type: profileType,
    profile_version: input.profile_version || 'baseline-v1',
    display_status: suppress ? 'INSUFFICIENT_PROFILE_DATA' : profileType === 'HISTORICAL_CUSTOMER_ICP' ? 'HISTORICAL_ICP' : 'BASELINE_ICP',
    opportunity_matrix,
    dimension_scores,
    reason_codes: [...new Set(reason_codes)],
    evidence_ids: [...new Set(evidenceIds)],
    rule_version: 'baseline-v1'
  };
};
